from pathlib import Path
import shutil
for name in ['.venv','.uv-cache']:
 p=Path(name)
 if p.exists(): shutil.rmtree(p)
for name in ['extract.py','alignment-preview.png','extraction-report.json']:
 Path(name).unlink(missing_ok=True)
for name in ['walk-front.gif','walk-back.gif','walk-right.gif','seated.gif','sheet.png']:
 p=Path(name)
 print(f'{p.name}: {p.stat().st_size} bytes')
PY"

